UPDATE system_settings SET remark='模板含 T 段(6位 YYMMDD 或 8位 YYYYMMDD 打印日期)时校验：超出 N 天或未来日期拒收；无 T 段的模板不受影响' WHERE setting_key='ai.scale.label_valid_days';
