UPDATE system_settings SET remark='审核通过后自动弹出 A5 单据打印(已接入：采购入库/采购退货/采购订单/盘点/报损/调拨/对账确认)，需 docs.print.a5 权限；是前端弹打印预览，非服务端静默打印' WHERE setting_key='doc.print.auto_a5';
UPDATE system_settings SET remark='打印机 USB 刷新后静默自动重连总闸：关=需到设备面板手动重连' WHERE setting_key='ops.printer_reconnect';
UPDATE system_settings SET remark='电子秤串口波特率(与秤说明书一致，常见 9600 / 4800)' WHERE setting_key='scale.baud';
