UPDATE system_settings SET remark='条码秤打印条码的前两位识别码(FFWWWWW 中的 FF)' WHERE setting_key='scale.tx.barcode_prefix';
UPDATE system_settings SET remark='常见 9600' WHERE setting_key='scale.tx.baud';
UPDATE system_settings SET remark='秤端编码(下拉选择，中文标签秤通用 GBK)' WHERE setting_key='scale.tx.charset';
UPDATE system_settings SET remark='2位部门号' WHERE setting_key='scale.tx.department';
UPDATE system_settings SET remark='如 COM3 / COM4' WHERE setting_key='scale.tx.port';
UPDATE system_settings SET remark='默认连接方式(下拉选择)' WHERE setting_key='scale.tx.port_type';
UPDATE system_settings SET remark='默认协议品牌(下拉选择)' WHERE setting_key='scale.tx.protocol';
UPDATE system_settings SET remark='网口秤 IP' WHERE setting_key='scale.tx.tcp_host';
UPDATE system_settings SET remark='常见 9100' WHERE setting_key='scale.tx.tcp_port';
UPDATE system_settings SET remark='是否同时下发会员价(依赖秤型号支持)' WHERE setting_key='scale.tx.use_member_price';
UPDATE system_settings SET remark='老板端「经营问答」答案自动朗读的开关(已生效，boss 端实时读取)；音色/语速在「语音播报」小节统一配置' WHERE setting_key='voice.assistant.enabled';
UPDATE system_settings SET remark='语音提问查价的回答播报；音色/语速在「语音播报」小节统一配置' WHERE setting_key='voice.price.enabled';
UPDATE system_settings SET remark='收银加购时播报商品名+价格(在 pos.cashier.tts 总开关之下的子开关)' WHERE setting_key='voice.product.enabled';
UPDATE system_settings SET remark='0.5~2 倍，1 为正常语速；收款播报建议 1~1.2' WHERE setting_key='voice.tts.rate';
UPDATE system_settings SET remark='空=自动选最佳中文声(女声优先)；设置页可下拉试听本机全部音色，带 ⭐ 为拟真人声' WHERE setting_key='voice.tts.voice';
UPDATE system_settings SET remark='开=员工登录必须使用「已授权设备」，新设备自动登记为待授权并上报管理后台；关=任何人知道账密即可在任意设备登录(不建议)' WHERE setting_key='pos.device.auth';
UPDATE system_settings SET remark='从服务器本机(127.0.0.1 / ::1)发起的登录跳过设备授权校验，用于避免「授权需要登录、登录需要授权」的引导死锁。手机与局域网其它电脑不受影响，仍须授权。不接受可关闭，但关闭后管理员换设备须靠恢复码或 npm run device:grant 解封' WHERE setting_key='pos.device.auth.loopback.bypass';
UPDATE system_settings SET remark='默认关。收银台为共用设备，一台设备需服务多个员工；开启后会变成「一台设备固定一个员工」，导致其他员工登不进。设备准入请用「配对码」' WHERE setting_key='pos.device.bind.employee';
UPDATE system_settings SET remark='收银员、库管 默认只允许 1 台设备(一台设备固定一个员工)；共享收银台请调高或关闭「设备绑定员工」' WHERE setting_key='pos.device.limit.cashier';
UPDATE system_settings SET remark='店长、财务、超级管理员 默认允许 2 台(手机 + 电脑/_PAD 各一)；超管另有应急恢复码兜底' WHERE setting_key='pos.device.limit.manager';
UPDATE system_settings SET remark='1 = 只能用一次(最安全)。共用收银台要一次放行多台时生成「不限次」码，或给每台设备分别生成一个码' WHERE setting_key='pos.device.pair.max.uses';
UPDATE system_settings SET remark='管理员生成的配对码在多少小时后失效。当天配对建议 24；跨天审批可设 72。过期后员工需重新找管理员要码' WHERE setting_key='pos.device.pair.ttl.hours';
UPDATE system_settings SET remark='超管被挡在门外时的兜底：登录时填写此码可强制通过并自动授权本设备。留空表示未启用(改用环境变量 DEVICE_RECOVERY_CODE)。生成后请妥善保管' WHERE setting_key='pos.device.recovery.hint';
UPDATE system_settings SET remark='开=设备必须用硬件私钥对登录挑战签名(设备码被抄到别的电脑/手机也登不进去)。需前端与 APK 均升级后再开启，否则旧设备全部无法登录' WHERE setting_key='pos.device.require.signature';
UPDATE system_settings SET remark='开=新设备登录后，旧设备的会话在 60 秒内失效(防同账号多地同时收银/改价)；关=允许多设备同时在线' WHERE setting_key='pos.device.single.session';
UPDATE system_settings SET remark='单个门店最多可登记的授权设备数(含待授权)。按「收银台数 + 老板/店长手机 + 备用机」的 1.5 倍设定，随时可调。超出后新设备无法登记' WHERE setting_key='pos.device.store.cap';
UPDATE system_settings SET remark='顾客副屏空闲轮播(JSON 数组：[{title,sub,emoji,image?}]，后台设置页可编辑)' WHERE setting_key='display.ads';
UPDATE system_settings SET remark='顾客副屏顶栏常驻欢迎语(店招取「商店信息 store.info.name」)' WHERE setting_key='display.welcome';
UPDATE system_settings SET remark='开=收银台全屏并强制置顶(盖住任务栏、Alt+Tab 也切不走，适合顾客可触碰的收银机)；关=全屏但可切换其他程序(默认)' WHERE setting_key='pos.desktop.kiosk_topmost';
UPDATE system_settings SET remark='关闭后主屏不再向顾客副屏推送购物明细/支付引导(副屏显示等待连接)' WHERE setting_key='pos.display.push';
UPDATE system_settings SET remark='小票机自动出票总开关(已配默认小票机时生效)；没配小票机走浏览器兜底，由「浏览器兜底打印」控制' WHERE setting_key='pos.print.auto';
UPDATE system_settings SET remark='未配置小票机时：开=自动弹浏览器打印预览兜底出票；关=绝不弹预览(明示未出票，可补打)。与小票机路径的「结账自动打印小票」互补' WHERE setting_key='pos.print.browser_fallback';
UPDATE system_settings SET remark='每单打印联数(默认 1；双联存根请设 2)' WHERE setting_key='pos.print.copies';
UPDATE system_settings SET remark='浏览器打印路径的自动出票开关(receipt 模块)；是否走浏览器兜底路径由「浏览器兜底打印」决定，本键只管该路径内是否自动打' WHERE setting_key='pos.receipt.auto_print';
UPDATE system_settings SET remark='小票纸宽度(毫米，常见 80 / 58，与打印机实际纸宽一致)' WHERE setting_key='pos.receipt.width';
UPDATE system_settings SET remark='收银完成后的收款金额语音提示(「收款 X 元，谢谢惠顾」)；音色在「语音播报」小节选择' WHERE setting_key='pos.voice_broadcast';
UPDATE system_settings SET remark='门店开业日期(YYYY-MM-DD)，作为经营报表起算日与会员分红资格窗口的基准' WHERE setting_key='init.opening_date';
UPDATE system_settings SET remark='开业日(init.opening_date)当天 00:06 起向全员广播本说明一次(员工端铃铛+老板端消息中心)；留空=不广播' WHERE setting_key='init.opening_note';
UPDATE system_settings SET remark='最多保留最近 N 份备份，超出循环删除最旧的一份(0=不限，仅按天数过期)；与「每日备份时间」「保留天数」共同生效' WHERE setting_key='ops.backup.keep_count';
UPDATE system_settings SET remark='备份目录总占用超过该值时，从最旧的备份开始删除直到达标(0=不按大小限制，仅按份数/天数清理)' WHERE setting_key='ops.backup.max_total_gb';
UPDATE system_settings SET remark='进价差异单超时未裁决 → 自动结案(认可)并升级告警' WHERE setting_key='chain.cost.adjust_window_h';
UPDATE system_settings SET remark='总部还没维护过某商品进价时，第一笔入库的实际进价自动作为标准进价，新品立即受进价保护' WHERE setting_key='chain.cost.auto_adopt_new';
UPDATE system_settings SET remark='同店同商品同向差异在该窗口内合并为一条，防刷屏' WHERE setting_key='chain.cost.merge_days';
UPDATE system_settings SET remark='关=门店申请新商品上架需要总部批准；开=申请后直接生效' WHERE setting_key='chain.product.self_apply';
UPDATE system_settings SET remark='true=允许受理店以现金直接退付他店订单(资金走店间往来台账)；false=强制走跨店冲减流程。默认关' WHERE setting_key='chain.return.cross_cash';
UPDATE system_settings SET remark='true=盘点盈余按棘轮规则允许抬高 L1 进价基准；false=盘盈只调数量不调价' WHERE setting_key='chain.variance.pickup_raise_l1';
UPDATE system_settings SET remark='单节点单日「退款/回补」入向总额上限，防会员资产被凭空增发(审计 F-02)。0=不限制(不建议)' WHERE setting_key='hq.member.cross_daily_limit';
